const fs = require("node:fs");
const path = require("node:path");

const {
  RUNTIME_PROFILES,
} = require("../../../shared/contracts/casework/caseworkContracts");

const CASEWORK_ENV_KEYS = Object.freeze([
  "CASEWORK_RUNTIME_PROFILE",
  "CASEWORK_DATA_ROOT",
  "CASEWORK_DB_PATH",
  "CASEWORK_UPLOADS_ROOT",
  "CASEWORK_LOG_ROOT",
  "CASEWORK_SQLITE_BUSY_TIMEOUT_MS",
  "APP_LOG_LEVEL",
  "AI_PROVIDER_BASE_URL",
  "AI_PROVIDER_API_KEY_ENV",
  "AI_DEFAULT_MODEL",
]);

function readStringEnv(env, key, fallback) {
  const value = env[key];
  if (value === undefined || value === null || value === "") {
    return fallback;
  }
  if (typeof value !== "string") {
    throw new TypeError(`${key} must be a string when provided.`);
  }
  if (value.includes("\u0000")) {
    throw new TypeError(`${key} must not contain null bytes.`);
  }
  return value;
}

function readIntegerEnv(env, key, fallback) {
  const rawValue = readStringEnv(env, key, String(fallback));
  const value = Number.parseInt(rawValue, 10);
  if (!Number.isInteger(value) || value < 0) {
    throw new TypeError(`${key} must be a non-negative integer.`);
  }
  return value;
}

function resolveAbsolutePath(baseCwd, candidatePath) {
  return path.resolve(baseCwd, candidatePath);
}

function ensureRuntimeProfile(value) {
  if (!RUNTIME_PROFILES.includes(value)) {
    throw new RangeError(
      `CASEWORK_RUNTIME_PROFILE must be one of: ${RUNTIME_PROFILES.join(", ")}.`,
    );
  }
}

function ensureEnvVarName(value) {
  if (!/^[A-Z][A-Z0-9_]*$/.test(value)) {
    throw new TypeError("AI_PROVIDER_API_KEY_ENV must be an environment variable name.");
  }
}

function loadCaseworkConfig(env = process.env, options = {}) {
  const cwd = options.cwd || process.cwd();
  const runtimeProfile = readStringEnv(
    env,
    "CASEWORK_RUNTIME_PROFILE",
    "local-workstation",
  );
  ensureRuntimeProfile(runtimeProfile);

  const dataRoot = resolveAbsolutePath(
    cwd,
    readStringEnv(env, "CASEWORK_DATA_ROOT", "./var/casework"),
  );
  const uploadsRoot = resolveAbsolutePath(
    cwd,
    readStringEnv(env, "CASEWORK_UPLOADS_ROOT", path.join(dataRoot, "uploads")),
  );
  const logsRoot = resolveAbsolutePath(
    cwd,
    readStringEnv(env, "CASEWORK_LOG_ROOT", path.join(dataRoot, "logs")),
  );
  const dbPath = resolveAbsolutePath(
    cwd,
    readStringEnv(env, "CASEWORK_DB_PATH", path.join(dataRoot, "sqlite", "casework.sqlite")),
  );
  const providerApiKeyEnv = readStringEnv(
    env,
    "AI_PROVIDER_API_KEY_ENV",
