from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
import os
from pathlib import Path


class CaseworkConfigurationError(ValueError):
    """Raised when the runtime contract is incomplete or unsafe."""


class RuntimeProfile(str, Enum):
    LOCAL_WORKSTATION = "local_workstation"
    ONPREM_SINGLE_VM = "onprem_single_vm"


def _require_env(env: dict[str, str], key: str) -> str:
    value = env.get(key, "").strip()
    if not value:
        raise CaseworkConfigurationError(f"Missing required environment variable: {key}")
    return value


def _resolve_absolute_root(raw_value: str, key: str) -> Path:
    candidate = Path(raw_value).expanduser()
    if not candidate.is_absolute():
        raise CaseworkConfigurationError(f"{key} must be an absolute path: {raw_value}")
    return candidate.resolve(strict=False)


def _ensure_within_root(candidate: Path, root: Path, key: str) -> Path:
    resolved = candidate.resolve(strict=False)
    try:
        resolved.relative_to(root)
    except ValueError as exc:
        raise CaseworkConfigurationError(
            f"{key} must stay within CASEWORK_APP_ROOT: {resolved}"
        ) from exc
    return resolved


def _resolve_scoped_path(raw_value: str, root: Path, key: str) -> Path:
    raw_path = Path(raw_value).expanduser()
    candidate = raw_path if raw_path.is_absolute() else root / raw_path
    return _ensure_within_root(candidate, root, key)


