const { DatabaseSync } = require("node:sqlite");

const {
  ensureCaseworkDirectories,
  loadCaseworkConfig,
} = require("../config/caseworkConfig");

function openCaseworkDatabase(dbPath, options = {}) {
  const db = new DatabaseSync(dbPath);
  db.enableDefensive(true);
  db.exec("PRAGMA foreign_keys = ON;");
  db.exec(`PRAGMA busy_timeout = ${options.busyTimeoutMs || 5000};`);
  db.exec("PRAGMA journal_mode = WAL;");
  return db;
}

function withTransaction(db, operation) {
  db.exec("BEGIN IMMEDIATE;");
  try {
    const result = operation(db);
    db.exec("COMMIT;");
    return result;
  } catch (error) {
    try {
      db.exec("ROLLBACK;");
    } catch {
      // Best effort rollback for callers that already lost the connection.
    }
    throw error;
  }
}

function bootstrapCaseworkDatabase(env = process.env, options = {}) {
  const config = loadCaseworkConfig(env, options);
  ensureCaseworkDirectories(config);
  const db = openCaseworkDatabase(config.dbPath, {
    busyTimeoutMs: config.sqliteBusyTimeoutMs,
  });
  return { config, db };
}

module.exports = {
  openCaseworkDatabase,
  withTransaction,
  bootstrapCaseworkDatabase,
};

