from __future__ import annotations

from dataclasses import dataclass
import json
import os

from backend.lib.config import CaseworkRuntimeConfig
from backend.lib.db import connect_sqlite
from backend.modules.casework.schema import CANONICAL_TABLES, initialize_casework_schema


@dataclass(frozen=True, slots=True)
class BootstrapResult:
    db_path: str
    runtime_profile: str
    canonical_tables: tuple[str, ...]


def bootstrap_casework_database(
    config: CaseworkRuntimeConfig,
) -> BootstrapResult:
    connection = connect_sqlite(config)
    try:
        initialize_casework_schema(connection)
    finally:
        connection.close()
    return BootstrapResult(
        db_path=str(config.db_path),
        runtime_profile=config.runtime_profile.value,
        canonical_tables=CANONICAL_TABLES,
    )


