"use strict";

const fs = require("node:fs");
const path = require("node:path");
const { initializeCaseworkSchema } = require("./schema");
const { resolveCaseworkConfig } = require("./config");

function loadBetterSqlite3() {
  return require("better-sqlite3");
}

function openCaseworkDatabase(config = resolveCaseworkConfig(), options = {}) {
  fs.mkdirSync(path.dirname(config.sqlitePath), { recursive: true });
  fs.mkdirSync(config.uploadsRoot, { recursive: true });
  fs.mkdirSync(config.exportsRoot, { recursive: true });

  const Database = options.Database || loadBetterSqlite3();
  const db = new Database(config.sqlitePath);
  db.pragma("journal_mode = WAL");
  db.pragma("foreign_keys = ON");
  initializeCaseworkSchema(db);
  return db;
}

module.exports = {
  openCaseworkDatabase,
  loadBetterSqlite3,
};

