class CaseworkPersistenceError(RuntimeError):
    """Raised when a repository transaction fails."""


def _extract_file_fields(file_reference: FileReference | None) -> tuple[object, ...]:
    if file_reference is None:
        return (None, None, None, None, None)
    return (
        file_reference.original_name,
        file_reference.storage_key,
        file_reference.media_type,
        file_reference.sha256_hex,
        file_reference.size_bytes,
    )


class CaseworkRepository:
    def __init__(self, connection: sqlite3.Connection) -> None:
        self._connection = connection

    @contextmanager
    def _transaction(self) -> Iterable[None]:
        try:
            self._connection.execute("BEGIN")
            yield
            self._connection.execute("COMMIT")
        except sqlite3.DatabaseError as exc:
            self._connection.execute("ROLLBACK")
            raise CaseworkPersistenceError(str(exc)) from exc

    def create_bando_bundle(
        self, bando: BandoRecord, requirements: list[RequirementRecord]
    ) -> None:
        with self._transaction():
            self._connection.execute(
