                    id, status, title,
                    source_original_name, source_storage_key, source_media_type,
                    source_sha256_hex, source_size_bytes, source_notes,
                    created_at, updated_at
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    bando.id,
                    bando.status.value,
                    bando.title,
                    *_extract_file_fields(bando.source_file),
                    bando.source_notes,
                    bando.created_at,
                    bando.updated_at,
                ),
            )
            for requirement in requirements:
                self._connection.execute(
                    """
                    INSERT INTO requirements (
                        id, bando_id, code, title, description, status,
                        reviewer_notes, created_at, updated_at
