"use strict";

const fs = require("node:fs");
const path = require("node:path");

const schemaPath = path.join(__dirname, "schema.sql");
const CASEWORK_SCHEMA_SQL = fs.readFileSync(schemaPath, "utf8");

function initializeCaseworkSchema(db) {
  db.pragma("foreign_keys = ON");
  db.exec(CASEWORK_SCHEMA_SQL);
  const violations = db.prepare("PRAGMA foreign_key_check").all();
  if (violations.length > 0) {
    const details = JSON.stringify(violations);
    throw new Error(`casework schema foreign key check failed: ${details}`);
  }
}

module.exports = {
  CASEWORK_SCHEMA_SQL,
  initializeCaseworkSchema,
};

